import { PLANS } from '@proton/payments';
import { APPS } from '@proton/shared/lib/constants';
import { getPlan } from '@proton/shared/lib/helpers/subscription';

import { user as mockUser, subscriptionBundlePro } from '../__mocks__/data';
import { getReminderPageConfig } from './reminderPageConfig';

jest.mock('@proton/shared/lib/helpers/subscription', () => ({
    __esModule: true,
    ...jest.requireActual('@proton/shared/lib/helpers/subscription'),
    getPlan: jest.fn(),
}));

const setMockPlan = (planName: PLANS) => {
    (getPlan as jest.Mock).mockReturnValue({
        MaxAddresses: 5,
        MaxCalendars: 1,
        MaxDomains: 1,
        MaxMembers: 1,
        MaxSpace: 536870912000,
        Name: planName,
    });
};

const user = {
    ...mockUser,
    canPay: true,
    hasNonDelinquentScope: true,
    hasPaidDrive: false,
    hasPaidMail: true,
    hasPaidPass: false,
    hasPaidVpn: false,
    isAdmin: false,
    isDelinquent: false,
    isFree: false,
    isMember: true,
    isPaid: true,
    isPrivate: false,
    isSelf: true,
    hasPassLifetime: false,
};

describe('getReminderPageConfig', () => {
    beforeEach(() => {
        jest.resetAllMocks();
    });

    test.each([
        [PLANS.MAIL, undefined],
        [PLANS.BUNDLE, PLANS.MAIL],
        [PLANS.FAMILY, undefined],
        [PLANS.DUO, PLANS.BUNDLE],
        [PLANS.VISIONARY, PLANS.FAMILY],
        [PLANS.DRIVE, undefined],
        [PLANS.MAIL_PRO, undefined],
        [PLANS.MAIL_BUSINESS, PLANS.MAIL_PRO],
        [PLANS.BUNDLE_PRO_2024, PLANS.MAIL_BUSINESS],
        [PLANS.BUNDLE_PRO, PLANS.MAIL_BUSINESS],
    ])(
        'given app is Mail and plan name is %s, should return the correct upsell plan, if any',
        (planName: PLANS, upsellPlanName: PLANS | undefined) => {
            setMockPlan(planName);
            const config = getReminderPageConfig({ app: APPS.PROTONMAIL, subscription: subscriptionBundlePro, user });

            expect(config?.upsellPlan).toEqual(upsellPlanName);
        }
    );
});

import { render } from '@testing-library/react';
import { addMonths, format, getUnixTime, startOfDay } from 'date-fns';

import type { SubscriptionModel } from '@proton/shared/lib/interfaces';
import { subscriptionMock, upcomingSubscriptionMock } from '@proton/testing/data';

import { ExpirationTime as B2BExpirationTime } from './b2bCommonConfig';
import { ExpirationTime as B2CExpirationTime } from './b2cCommonConfig';

const cases = [
    {
        name: 'B2C subscription ending at renewal',
        renderExpiration: (subscription: SubscriptionModel) => (
            <B2CExpirationTime subscription={subscription} cancellablePlan />
        ),
        showsDate: true,
    },
    {
        name: 'B2C subscription ending immediately',
        renderExpiration: (subscription: SubscriptionModel) => <B2CExpirationTime subscription={subscription} />,
        showsDate: false,
    },
    {
        name: 'B2B subscription ending at renewal',
        renderExpiration: (subscription: SubscriptionModel) => (
            <B2BExpirationTime subscription={subscription} isChargeBeeUser />
        ),
        showsDate: true,
    },
    {
        name: 'B2B subscription ending immediately',
        renderExpiration: (subscription: SubscriptionModel) => <B2BExpirationTime subscription={subscription} />,
        showsDate: false,
    },
];

it.each(cases)('shows the current term expiry for $name', ({ renderExpiration, showsDate }) => {
    const currentEnd = addMonths(startOfDay(new Date()), 2);
    const upcomingEnd = addMonths(currentEnd, 12);
    const subscription = {
        ...subscriptionMock,
        PeriodEnd: getUnixTime(currentEnd),
        UpcomingSubscription: { ...upcomingSubscriptionMock, PeriodEnd: getUnixTime(upcomingEnd) },
    };

    const { container } = render(renderExpiration(subscription));
    const expiry = container.querySelector('time');

    expect(expiry).toHaveAttribute('dateTime', format(currentEnd, 'yyyy-MM-dd'));
    expect(expiry).not.toHaveAttribute('dateTime', format(upcomingEnd, 'yyyy-MM-dd'));
    if (showsDate) {
        expect(expiry).toHaveTextContent(format(currentEnd, 'PP'));
    }
});
